BASE <http://rdf.biogateway.eu/graph/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX taxon: <http://purl.obolibrary.org/obo/ncbitaxon#>
SELECT (count( DISTINCT ?s) as ?taxon )
WHERE {
GRAPH <taxon> {
  {?s taxon:has_rank <http://purl.obolibrary.org/obo/NCBITaxon_species> .}
}
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?ancestor ?level
WHERE {
  {
    SELECT ?taxon ?ancestor
    WHERE {
      ?taxon rdfs:subClassOf ?ancestor
    }
  }
  OPTION (
    TRANSITIVE,
    t_distinct,
    t_in(?taxon),
    t_out(?ancestor),
    t_min(1),
    t_step('step_no') AS ?level
  )
  FILTER (
    ?taxon = <http://purl.obolibrary.org/obo/NCBITaxon_9606>
  )
}
ORDER BY ?level

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?sucesor ?level
WHERE {
  {
    SELECT ?taxon ?sucesor
    WHERE {
      ?sucesor rdfs:subClassOf ?taxon
    }
  }
  OPTION (
    TRANSITIVE,
    t_distinct,
    t_in(?taxon),
    t_out(?sucesor),
    t_min(1),
    t_step('step_no') AS ?level
  )
  FILTER (
    ?taxon = <http://purl.obolibrary.org/obo/NCBITaxon_9606>
  )
}
ORDER BY ?level

BASE <http://rdf.biogateway.eu/graph/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX taxon: <http://purl.obolibrary.org/obo/ncbitaxon#>
PREFIX oboInOwl: <http://www.geneontology.org/formats/oboInOwl#>
SELECT distinct ?s ?label ?syn
WHERE {
GRAPH <taxon> {
     ?s taxon:has_rank <http://purl.obolibrary.org/obo/NCBITaxon_species> .
     ?s rdfs:label ?label .
     OPTIONAL {?s oboInOwl:hasRelatedSynonym ?syn . }
	}
}
limit 10

BASE <http://rdf.biogateway.eu/graph/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?graph ?s ?o ?t ?l
WHERE {
GRAPH ?graph {
   ?s ?r "APOC1" .
   ?s <http://semanticscience.org/resource/SIO_010078> ?o .
   ?s <http://purl.obolibrary.org/obo/RO_0002162> ?t .
}
graph ?g {
   ?t rdfs:label ?l .
}
}

